#include "military_attack_damage_core.hpp"
#include "dynamic_land_allocation.hpp"
#include "resident/domains/travel/movement_exact_detail.hpp"
#include <algorithm>
#include <limits>
#include <set>
#include <tuple>
namespace hanmo::resident {using namespace movement_detail;
namespace {
StableId ref_key(const SourceRef& ref){return std::to_string(ref.domain.size())+":"+ref.domain+std::to_string(ref.kind.size())+":"+ref.kind+std::to_string(ref.id.size())+":"+ref.id;}
Integer plus_checked(Integer a,Integer value,const StableId& id){if(value>0&&a>std::numeric_limits<Integer>::max()-value)fail("DynamicMilitaryMoraleAggregationOverflow",id);if(value<0&&a<std::numeric_limits<Integer>::min()-value)fail("DynamicMilitaryMoraleAggregationOverflow",id);return a+value;}
bool optional_ref_equal(const std::optional<SourceRef>& a,const std::optional<SourceRef>& b){return bool(a)==bool(b)&&(!a||same_source(*a,*b));}
}
Outcome<DynamicLandMergedAllocation> merge_dynamic_land_member_allocations(const std::vector<DynamicLandAllocationUnit>& units,const std::vector<DynamicLandStrikeDamage>& strikes,const std::vector<DynamicLandQualifiedSupport>& supports,DynamicLandCasualtyRule rule){return guard<DynamicLandMergedAllocation>([&]{
 if(rule!=DynamicLandCasualtyRule::legacy_factors&&rule!=DynamicLandCasualtyRule::commanded_factors)fail("DynamicMilitaryOriginalCasualtyRuleRequired");
 struct UnitWork {const DynamicLandAllocationUnit* original=nullptr;std::size_t residual_cursor=0;Integer morale_loss=0;std::vector<std::size_t> allocated;};
 std::vector<UnitWork> work;work.reserve(units.size());std::set<StableId> members;StableId previous;
 for(const auto& unit:units){if(unit.unit_ref.empty()||unit.unit_ref<=previous||unit.original_morale<0||unit.original_morale>100||unit.original_fit_ids.size()>500||!std::is_sorted(unit.original_fit_ids.begin(),unit.original_fit_ids.end()))fail("DynamicMilitaryStrikeSnapshotMismatch",unit.unit_ref);previous=unit.unit_ref;for(const auto& member:unit.original_fit_ids)if(member.empty()||!members.insert(member).second)fail("DynamicMilitaryDuplicateOriginalMember",member);work.push_back({&unit,0,0,{}});}
 auto find_unit=[&](const StableId& id)->UnitWork&{auto at=std::lower_bound(work.begin(),work.end(),id,[](const auto& u,const StableId& key){return u.original->unit_ref<key;});if(at==work.end()||at->original->unit_ref!=id)fail("DynamicMilitaryStrikeUnitRequired",id);return *at;};
 std::set<StableId> effects,token_ids,supporter_ids;std::tuple<StableId,Integer,Integer> prior;bool first=true;
 for(const auto& strike:strikes){auto key=std::make_tuple(strike.attacker_unit_ref,strike.action_instance_ordinal,strike.effect_ordinal);if(!source_valid(strike.effect_ref)||strike.action_ref.empty()||strike.action_instance_ordinal<0||strike.effect_ordinal<0||strike.attacker_unit_ref==strike.target_unit_ref||strike.raw_casualties<0||strike.raw_casualties>500||strike.original_tactic_morale<0||strike.original_tactic_morale>100||(strike.original_flank_morale!=0&&strike.original_flank_morale!=5&&strike.original_flank_morale!=10)||!effects.insert(ref_key(strike.effect_ref)).second||(!first&&key<=prior))fail("DynamicMilitaryCanonicalStrikeSetRequired",strike.effect_ref.id);find_unit(strike.attacker_unit_ref);find_unit(strike.target_unit_ref);prior=key;first=false;}
 for(const auto& support:supports){const auto& token=support.token;if(!source_valid(token.activation_ref)||token.supporter_unit_ref==token.target_unit_ref||token.qualification_source_refs.empty()||!token_ids.insert(ref_key(token.activation_ref)).second||!supporter_ids.insert(token.supporter_unit_ref).second)fail("DynamicMilitaryQualifiedSupportMismatch",token.activation_ref.id);find_unit(token.supporter_unit_ref);find_unit(token.target_unit_ref);if(token.consumed_by_effect_ref&&!source_valid(*token.consumed_by_effect_ref))fail("DynamicMilitarySupportConsumptionSourceRequired",token.activation_ref.id);}
 DynamicLandMergedAllocation out;out.strikes.reserve(strikes.size());std::set<StableId> target_support_consumed,activation_consumed;
 auto allocate=[&](UnitWork& unit,Integer count,const DynamicLandStrikeDamage& strike,bool support,std::vector<StableId>& selected){if(count<0||std::size_t(count)>unit.original->original_fit_ids.size()-unit.residual_cursor)fail("DynamicMilitaryResidualAllocationMismatch",unit.original->unit_ref);for(Integer i=0;i<count;++i){const auto& member=unit.original->original_fit_ids[unit.residual_cursor++];selected.push_back(member);unit.allocated.push_back(out.member_allocations.size());out.member_allocations.push_back({member,unit.original->unit_ref,strike.effect_ref,strike.target_unit_ref,support,{}});}};
 for(const auto& strike:strikes){auto& target=find_unit(strike.target_unit_ref);const auto count=std::min<Integer>(strike.raw_casualties,Integer(target.original->original_fit_ids.size()-target.residual_cursor));const DynamicSupportToken* selected=nullptr;
  if(count>0&&!target_support_consumed.count(strike.target_unit_ref)){for(const auto& candidate:supports){const auto& token=candidate.token;if(token.target_unit_ref!=strike.target_unit_ref||token.consumed_by_effect_ref||activation_consumed.count(ref_key(token.activation_ref)))continue;if(!selected||token.supporter_unit_ref<selected->supporter_unit_ref)selected=&token;}if(selected){target_support_consumed.insert(strike.target_unit_ref);activation_consumed.insert(ref_key(selected->activation_ref));}}
  DynamicLandStrikeAllocation row;row.effect_ref=strike.effect_ref;row.raw_casualties=strike.raw_casualties;Integer share=0;
  if(selected){auto& supporter=find_unit(selected->supporter_unit_ref);share=original_military_support_share(count,Integer(supporter.original->original_fit_ids.size()-supporter.residual_cursor));row.consumed_support_activation_ref=selected->activation_ref;row.supporter_unit_ref=selected->supporter_unit_ref;allocate(supporter,share,strike,true,row.support_member_ids);if(share>0){const auto loss=original_military_casualty_morale_loss(share,Integer(supporter.original->original_fit_ids.size()),rule==DynamicLandCasualtyRule::commanded_factors);supporter.morale_loss=plus_checked(supporter.morale_loss,loss,supporter.original->unit_ref);}}
  const auto direct=count-share;row.actual_target_count=direct;row.actual_support_count=share;allocate(target,direct,strike,false,row.target_member_ids);
  if(count>0){const auto original_loss=original_military_casualty_morale_loss(direct,Integer(target.original->original_fit_ids.size()),rule==DynamicLandCasualtyRule::commanded_factors,strike.original_flank_morale);target.morale_loss=plus_checked(target.morale_loss,plus_checked(original_loss,strike.original_tactic_morale,target.original->unit_ref),target.original->unit_ref);}
  out.strikes.push_back(std::move(row));
 }
 // A unit's one residual vector is shared by all direct and support allocations.
 // Classify its total actual members once, preserving the original sorted-fit rule.
 for(auto& unit:work){std::sort(unit.allocated.begin(),unit.allocated.end(),[&](std::size_t a,std::size_t b){return out.member_allocations[a].member_id<out.member_allocations[b].member_id;});for(std::size_t i=0;i<unit.allocated.size();++i)out.member_allocations[unit.allocated[i]].resulting_status=original_military_casualty_is_wounded(Integer(i),Integer(unit.allocated.size()),rule==DynamicLandCasualtyRule::commanded_factors)?"wounded":"dead";if(!unit.allocated.empty()||unit.morale_loss){const auto after=unit.morale_loss>=unit.original->original_morale?0:unit.original->original_morale-unit.morale_loss;out.morale_changes.push_back({unit.original->unit_ref,unit.original->original_morale,-unit.morale_loss,after});}}
 std::sort(out.member_allocations.begin(),out.member_allocations.end(),[](const auto& a,const auto& b){return std::tie(a.unit_ref,a.member_id)<std::tie(b.unit_ref,b.member_id);});return out;
});}
Status validate_dynamic_land_member_allocations(const std::vector<DynamicLandAllocationUnit>& units,const std::vector<DynamicLandStrikeDamage>& strikes,const std::vector<DynamicLandQualifiedSupport>& supports,DynamicLandCasualtyRule rule,const DynamicLandMergedAllocation& saved){return status([&]{const auto expected=take(merge_dynamic_land_member_allocations(units,strikes,supports,rule));if(expected.strikes.size()!=saved.strikes.size()||expected.member_allocations.size()!=saved.member_allocations.size()||expected.morale_changes.size()!=saved.morale_changes.size())fail("DynamicMilitaryMergedAllocationCoverageMismatch");for(std::size_t i=0;i<expected.strikes.size();++i){const auto& a=expected.strikes[i];const auto& c=saved.strikes[i];if(!same_source(a.effect_ref,c.effect_ref)||a.raw_casualties!=c.raw_casualties||a.actual_target_count!=c.actual_target_count||a.actual_support_count!=c.actual_support_count||!optional_ref_equal(a.consumed_support_activation_ref,c.consumed_support_activation_ref)||a.supporter_unit_ref!=c.supporter_unit_ref||a.target_member_ids!=c.target_member_ids||a.support_member_ids!=c.support_member_ids)fail("DynamicMilitaryStrikeAllocationMismatch",c.effect_ref.id);}for(std::size_t i=0;i<expected.member_allocations.size();++i){const auto& a=expected.member_allocations[i];const auto& c=saved.member_allocations[i];if(a.member_id!=c.member_id||a.unit_ref!=c.unit_ref||!same_source(a.effect_ref,c.effect_ref)||a.direct_target_unit_ref!=c.direct_target_unit_ref||a.support_share!=c.support_share||a.resulting_status!=c.resulting_status)fail("DynamicMilitaryMemberAllocationMismatch",c.member_id);}for(std::size_t i=0;i<expected.morale_changes.size();++i){const auto& a=expected.morale_changes[i];const auto& c=saved.morale_changes[i];if(a.unit_ref!=c.unit_ref||a.before_morale!=c.before_morale||a.delta!=c.delta||a.after_morale!=c.after_morale)fail("DynamicMilitaryMoraleAggregationMismatch",c.unit_ref);}});}
}
